package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import com.lianxibu.site.repository.jobs.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;

/** Original native jobs only; the current member and business writer permission are separate providers. */
class CatalogVersionJobFactsTest extends CatalogVersionQualificationTest {
    JdbcCatalogVersionJobFacts storage(){return new JdbcCatalogVersionJobFacts(f.source,f.category);}
    CatalogVersionQualificationProjection.Projection projection(){return service.readProjection(f.category,"fictional-entity","fictional-analysis","fictional-current-item",f.clock.instant()).orElseThrow();}
    JdbcCatalogVersionJobFacts.Snapshot capture(){var p=projection();var tx=new TransactionTemplate(f.tx);tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);return tx.execute(s->storage().capture(p.rootId(),p.claimTargetHash()));}
    @Test void FourCategoryFullOriginalInputRequestResultClaimAndSendFingerprintRechecksInTheNativeWriter(){for(String category:List.of("agent","skill","workflow","model")){initialize(category,false);var p=projection();var original=capture();assertTrue(original.rows().stream().anyMatch(r->"ai_attempt".equals(r.scalars().get(1))));assertTrue(original.rows().stream().anyMatch(r->"worker_claim".equals(r.scalars().get(27))));assertTrue(original.rows().stream().anyMatch(r->"input".equals(r.scalars().get(5))));assertTrue(original.rows().stream().anyMatch(r->"result".equals(r.scalars().get(5))));var tx=new TransactionTemplate(f.tx);tx.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);assertEquals(original,tx.execute(s->storage().lockAndRead(p.rootId(),p.claimTargetHash())));assertThrows(UnsupportedOperationException.class,()->original.rows().clear());assertFalse(original.toString().contains("fictional"));assertEquals(1,f.sends);}}
    @Test void OriginalRawPayloadAndClaimHashesSendOrLatestIntentCannotSilentlyChangeUnderTheCapturedProof(){for(String fault:List.of("input","request","claim","send","intent")){initialize("agent",false);var p=projection();var original=capture();switch(fault){case "input"->f.jdbc.update("UPDATE jobs SET payload_json=? WHERE owner_job_id=? AND purpose='input'","{\"fictional_changed\":true}",p.rootId());case "request"->f.jdbc.update("UPDATE jobs SET request_json=? WHERE id=?","{\"fictional_changed\":true}",f.identity.attemptId());case "claim"->f.jdbc.update("UPDATE jobs SET action_payload=? WHERE target_type='worker_claim'","{\"fictional_changed\":true}");case "send"->f.jdbc.update("UPDATE jobs SET send_authorized_at=NULL WHERE id=?",f.identity.attemptId());case "intent"->f.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE record_kind='generation_intent'");}var tx=new TransactionTemplate(f.tx);tx.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);assertNotEquals(original,tx.execute(s->storage().lockAndRead(p.rootId(),p.claimTargetHash())));}}
    @Test void WrongTransactionsForeignCategoryRoleAndClaimCannotBeAcceptedAsOriginalFacts(){var p=projection();assertThrows(RuntimeException.class,()->storage().capture(p.rootId(),p.claimTargetHash()));var tx=new TransactionTemplate(f.tx);assertThrows(RuntimeException.class,()->tx.execute(s->storage().capture(p.rootId(),p.claimTargetHash())));tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);assertThrows(RuntimeException.class,()->tx.execute(s->storage().lockAndRead(p.rootId(),p.claimTargetHash())));assertThrows(RuntimeException.class,()->tx.execute(s->new JdbcCatalogVersionJobFacts(f.source,"skill").capture(p.rootId(),p.claimTargetHash())));assertThrows(RuntimeException.class,()->tx.execute(s->storage().capture(p.rootId(),"d".repeat(64))));f.jdbc.update("UPDATE jobs SET task_type='agent_dedup' WHERE id=?",p.rootId());assertThrows(RuntimeException.class,()->tx.execute(s->storage().capture(p.rootId(),p.claimTargetHash())));}
    @Test void ExactRelatedRowAndRawBytesCapacityRejectBeforeAnyWideTextEntersTheResult(){var p=projection();f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-capacity-seed",p.rootId(),"c".repeat(64)),k->null,c->{var records=new JdbcJobRecords(f.source);for(int n=0;n<=JdbcCatalogVersionJobFacts.MAX_ROWS;n++)records.putPart(new JdbcJobRecords.Part("fictional-cap-"+n,p.rootId(),"input","fictional-cap",n,"{}",CanonicalJson.hash(CanonicalJson.Domain.INPUT_PART,CanonicalJson.parse("{}"))),f.clock.instant());return true;});var tx=new TransactionTemplate(f.tx);tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);assertThrows(JdbcCatalogVersionJobFacts.CapacityRejected.class,()->tx.execute(s->storage().capture(p.rootId(),p.claimTargetHash())));initialize("agent",false);var good=projection();f.jdbc.update("UPDATE jobs SET action_payload=? WHERE target_type='worker_claim'","{\"fictional_long\":\""+"x".repeat(3145728)+"\"}");var nativeRead=new TransactionTemplate(f.tx);nativeRead.setReadOnly(true);nativeRead.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);assertThrows(JdbcCatalogVersionJobFacts.CapacityRejected.class,()->nativeRead.execute(s->storage().capture(good.rootId(),good.claimTargetHash())));}
}
